var hasCycle = function(head) {
    // Tortoise (slow) moves 1 step, hare (fast) moves 2 steps
    let slow = head;
    let fast = head;

    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;

        // If they meet, a cycle exists
        if (slow === fast) {
            return true;
        }
    }

    // fast reached the end — no cycle
    return false;
};
